/** Situations et phrases du quotidien (26/10/2026). Allemand pour francophone : chaque phrase accepte plusieurs formulations correctes. */

/** Les formes élidées françaises (« j'habite », « l'allemand ») sont un seul mot pour la comparaison : on les ajoute aux listes. */
function withElisions(keys: string[][]): string[][] {
  return keys.map((group) => {
    const extra = group.flatMap((word) => /^[aeiouyhéèêàâîôûœ]/i.test(word) ? ["l", "d", "j", "m", "n", "s", "t", "c", "qu"].map((letter) => `${letter}'${word}`) : []);
    return [...group, ...extra];
  });
}

